type broadcastHandler struct {
	mu     sync.Mutex
	values map[string]map[int]int64
}

func (bh *broadcastHandler) handleBroadcast(ctx context.Context, msg go.Message, body interface{}) error {
	v := body.(map[string]interface{})
	if message, ok := v["message"].(float64); ok {
		msgIDs := msg.GetMsgIDs()
		for _, reqID := range msgIDs {
			bh.mu.Lock()
			key := fmt.Sprintf("%s-%d", msg.Node(), reqID)
			if bh.values == nil {
				bh.values = make(map[string]map[int]int64)
			}
			if bh.values[key] == nil {
				bh.values[key] = make(map[int]int64)
			}
			bh.values[key][int(message)] = 1
			bh.mu.Unlock()
			msg.Reply(gomodel.NewReply(reqID, true), go.Node{Message: message})
		}
	}
	return nil
}

func main() {
	node := maelstrom.NewNode()
	handler := &broadcastHandler{}

	node.Handle("broadcast", handleBroadcast)
